<script setup>
import { onMounted, ref } from 'vue'
import BrandHeader from '@/components/BrandHeader.vue'
import SearchBar from '@/components/SearchBar.vue'
import Icon from '@/components/Icon.vue'
import { action } from '@/services/app'
import { getEducationProductList } from '@/api/product'

const data = ref({ categories: [], products: [] })
const categoryIcons = ['medal', 'book', 'settings', 'gift', 'cart']
const categoryIcon = item => { const index = data.value.categories.indexOf(item); return categoryIcons[index] || 'grid' }
const normalizeProduct = item => ({ id: item.id, productType: item.productType, title: item.name, image: item.coverUrl || '', price: item.price === null || item.price === undefined ? '咨询' : String(item.price), old: '', sold: '', tag: item.productType === 'COURSE' ? '课程商品' : item.productType === 'SERVICE' ? '服务商品' : '教材教具' })
const productTypeLabel = type => type === 'COURSE' ? '课程商品' : type === 'SERVICE' ? '服务商品' : '教材教具'
onMounted(async () => {
  try {
    const productRows = await getEducationProductList()
    const products = Array.isArray(productRows) ? productRows.map(normalizeProduct) : []
    const categories = ['全部商品', ...new Set(products.map(item => productTypeLabel(item.productType)).filter(Boolean))]
    data.value = {
      categories: categories.length > 1 ? categories : ['全部商品'],
      products
    }
  } catch (error) {
    data.value = { categories: [], products: [] }
  }
})
</script>

